CONTACTS=[
 ('email','Почта','dem.morozov@gmail.com','mailto:dem.morozov@gmail.com','Для ссылок, материалов и подробного описания задачи.'),
 ('phone','Телефон','+7 903 392-22-29','tel:+79033922229','Чтобы обсудить задачу голосом.'),
 ('telegram','Telegram','@dem2014','https://t.me/dem2014','Для короткого вопроса и начала разговора.'),
 ('max','MAX','Написать в MAX','https://max.ru/u/f9LHodD0cOKsTMRTtHDrBCx9IUwlPCT_77oJkGTxYU2zWOl3LgWbfqpRnKA','Выберите привычный мессенджер.')]
PATHS={'email':'M3 5h18v14H3V5Zm0 1 9 7 9-7','phone':'M6 3H3c-1 8 10 19 18 18v-3l-5-2-2 3a17 17 0 0 1-7-7l3-2-2-5Z','telegram':'m3 10 18-7-4 18-6-6-4 3v-5l10-7-12 5Z','max':'M4 4h16v12h-9l-7 5V4Zm4 4h8m-8 4h5'}
def icon(key):
 if key in ('telegram','max'):
  from stage9 import messenger_icon
  return messenger_icon(key)
 return f'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="{PATHS[key]}"/></svg>'

def links(compact=False):
 return '<div class="'+('public-contact-compact' if compact else 'public-contact-list')+'">'+''.join(f'<a href="{href}"'+(' target="_blank" rel="noopener noreferrer"' if href.startswith('https:') else '')+f'>{icon(key)}<span><b>{label}</b><strong>{('Написать' if compact and key=='max' else value)}</strong>'+('' if compact else f'<small>{description}</small>')+'</span></a>' for key,label,value,href,description in CONTACTS)+'</div>'
def contacts(body):
 start=body.index('<aside>');end=body.index('</aside>',start)+len('</aside>')
 aside='<aside class="contact-hub"><span class="eyebrow">НАПРЯМУЮ, БЕЗ ПОСРЕДНИКОВ</span><h2>Удобный способ<br>начать разговор</h2><p class="contact-hub-intro">Опишите, что нужно сделать. Можно прислать ссылку на сайт или короткий список задач.</p>'+links()+'<div class="contact-location"><b>Оренбург · Работаем дистанционно</b><span>Формат и время разговора согласуем.</span></div></aside>'
 return body[:start]+aside+body[end:]
def prices(intro,btn):
 body=intro('Стоимость','Начните с нужного результата,<br>а не с большого проекта.','Можно запустить небольшой сайт, улучшить существующий или сначала спроектировать систему. До работы фиксируем состав, ограничения и стоимость.')
 plans=[('Старт','Показать услуги','от 20 000 ₽','Сайт с понятным предложением и способом связи.',[('Лендинг · от 20 000 ₽','Одна страница до 6 блоков, готовые материалы, адаптация, одна форма в согласованный канал, базовые метаданные и проверка. Один общий список правок.'),('Сайт компании · от 50 000 ₽','До 5 страниц на общей дизайн-системе, готовые материалы и одна форма. Два общих списка правок. CMS, каталог, тексты и интеграции — отдельная смета.')],'Обсудить сайт','websites'),('Развитие','Улучшить работу','от 7 500 ₽','Начать с конкретной проблемы или небольшого объёма.',[('Проверка сценария · от 7 500 ₽','До 3 типовых страниц и один путь посетителя. Наблюдения, воспроизведение, приоритеты и критерии исправления. Исправления отдельно.'),('Аудит · от 15 000 ₽','Одно направление проверки, до 10 типовых страниц и одна форма. Отчёт и следующие задачи. Без комплексного code/security-аудита.'),('SEO · от 15 000 ₽ / месяц','Один регион, до 3 согласованных страниц: диагностика, запросы, план, заголовки, метаданные и структура, отчёт. Пакет до 5 страниц — от 25 000 ₽ / месяц. Без программирования, больших текстов и гарантии позиций.'),('Простая интеграция · от 15 000 ₽','Один односторонний сценарий между двумя системами, до 5 полей, проверенный API, журнал ошибок и тест результата. Без 1С, оплаты и миграции. Только после проверки совместимости.')],'Обсудить развитие','unsure'),('Система','Определить первую версию','от 15 000 ₽','Сначала сценарии и схемы, затем отдельная оценка разработки.',[('Проектирование · от 15 000 ₽','Один сценарий, до двух ролей и 3 схематичных экранов. Документ, карта действий и данных, ограничения и план реализации. Одна итерация уточнений.'),('Прототип · от 25 000 ₽','Один процесс, до 5 экранов и двух ролей, кликабельный путь на вымышленных данных. Одна итерация правок. Без серверного хранения, реальных подключений и отправок; это демонстрация, не готовая CRM.'),('Рабочая автоматизация · от 90 000 ₽','Один процесс, до двух ролей, без внешних интеграций. Поля, статусы и проверки фиксируем до сметы. Полная система из отраслевых примеров оценивается отдельно.')],'Определить первую версию','applications')]
 body+='<section class="wrap section compact solution-prices">'
 for i,(label,title,price,aim,items,action,service) in enumerate(plans):
  body+=f'<article class="solution-price"><span class="eyebrow">0{i+1} / {label}</span><h2>{title}</h2><strong class="solution-price-value">{price}</strong><p>{aim}</p><div class="price-options">'+''.join(f'<details'+(' open' if j==0 else '')+f'><summary>{name}<span aria-hidden="true">+</span></summary><p>{scope}</p></details>' for j,(name,scope) in enumerate(items))+'</div>'+btn(action,'?service='+service)+'</article>'
 body+='</section><section class="wrap price-conditions"><p>Точную стоимость и срок фиксируем после проверки материалов, доступов и объёма. Домен, хостинг, лицензии и сторонние сервисы оплачиваются отдельно. Новые задачи сначала оцениваем, затем выполняем.</p><p>Бриф, договор и оплата по этапам 30/40/30; для крупного проекта этапы согласуем отдельно. 30 календарных дней после запуска исправляем ошибки согласованного функционала. Для аудита и проектирования оплату и передачу определяем по результату услуги.</p></section>'
 body+='<section class="soft-section"><div class="wrap section"><div class="section-heading"><div><span class="eyebrow">ДРУГИЕ ЗАДАЧИ</span><h2>Начнём с того,<br>что уже есть</h2></div><p>Состав проверяем до сметы. Выберите задачу и расскажите о текущем проекте.</p></div><div class="pricing-task-links">'
 for service,title,detail in [('websites','Интернет-магазин','По составу каталога и заказа: платформа, товары, оплата, доставка и обмен.'),('redesign','Редизайн','После разбора текущего сайта. Проверка сценария — от 7 500 ₽; дизайн, вёрстка и перенос отдельно.'),('support','Небольшая доработка','От 3 000 ₽ за согласованный пакет до 2 часов. Диагностика знакомого проекта и объём уточняются до работы.'),('applications','Сложное приложение','По составу проекта: сценарии, роли, данные и подключения. Проектирование и прототип — отдельные результаты.')]:
  body+=f'<a href="contacts.html?service={service}"><h3>{title}</h3><p>{detail}</p><span aria-hidden="true">↗</span></a>'
 return body+'</div></div></section>'
